#include <bits/stdc++.h>
using namespace std;

int n, LOG;
vector<vector<int>> up;                  // up[k][v] = v 의 2^k 번째 조상
vector<int> dep;
vector<long long> dist;                  // 거리 합은 int 를 넘을 수 있어요

int lca(int a, int b) {
    if (dep[a] < dep[b]) swap(a, b);
    int diff = dep[a] - dep[b];
    for (int k = 0; k < LOG; k++)        // 1) 깊이 맞추기
        if (diff >> k & 1) a = up[k][a];
    if (a == b) return a;
    for (int k = LOG - 1; k >= 0; k--)   // 2) 조상이 달라지는 동안 함께 올리기
        if (up[k][a] != up[k][b]) a = up[k][a], b = up[k][b];
    return up[0][a];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    vector<vector<pair<int, int>>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b, w;
        cin >> a >> b >> w;
        g[a].push_back({b, w});
        g[b].push_back({a, w});
    }
    LOG = 1;
    while ((1 << LOG) <= n) LOG++;       // 2^LOG > n
    up.assign(LOG, vector<int>(n + 1, 1)); // 루트(1)의 조상은 자기 자신
    dep.assign(n + 1, 0);
    dist.assign(n + 1, 0);
    vector<bool> seen(n + 1, false);
    queue<int> q;
    q.push(1);
    seen[1] = true;
    while (!q.empty()) {                 // BFS 로 부모·깊이·거리
        int v = q.front();
        q.pop();
        for (auto [to, w] : g[v]) {
            if (seen[to]) continue;
            seen[to] = true;
            up[0][to] = v;
            dep[to] = dep[v] + 1;
            dist[to] = dist[v] + w;
            q.push(to);
        }
    }
    for (int k = 1; k < LOG; k++)        // k 를 바깥 반복으로
        for (int v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];

    int Q;
    cin >> Q;
    while (Q--) {
        int a, b;
        cin >> a >> b;
        int c = lca(a, b);
        cout << c << ' ' << dist[a] + dist[b] - 2 * dist[c] << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// 진입·탈출 시각으로 '조상인가' 를 O(1) 에 확인하기
int main() {
    vector<vector<int>> children = {{}, {2, 3}, {4, 5}, {6}, {}, {}, {}};
    int n = 6, timer = 0;
    vector<int> tin(n + 1), tout(n + 1);
    vector<pair<int, bool>> st = {{1, false}};
    while (!st.empty()) {                // 반복 DFS: 들어갈 때와 나올 때 시각을 적어요
        auto [v, leaving] = st.back();
        st.pop_back();
        timer++;
        if (leaving) { tout[v] = timer; continue; }
        tin[v] = timer;
        st.push_back({v, true});
        for (int i = (int)children[v].size() - 1; i >= 0; i--) st.push_back({children[v][i], false});
    }
    auto is_ancestor = [&](int a, int b) { return tin[a] <= tin[b] && tout[b] <= tout[a]; };
    for (int v = 1; v <= n; v++) cout << v << ':' << tin[v] << '-' << tout[v] << (v < n ? ' ' : '\n');
    cout << boolalpha << is_ancestor(1, 5) << ' ' << is_ancestor(2, 5) << ' '
         << is_ancestor(3, 5) << ' ' << is_ancestor(5, 5) << '\n';
    return 0;
}
